# Keep the input/output contract beside short code excerpts.
code_contracts = {
    "sunpy": ("A representative FITS file", "Observation time, wavelength, and units"),
    "persistence": ("The latest observed reading in each window", "One 30-minute-ahead prediction per window"),
    "stage": ("Your source, configuration, and dataset version", "A saved result that can be restored after restart"),
    "sweep": ("Six predefined configurations", "Six tracked training runs with matching metrics"),
}
for row in slides:
    if row["key"] in code_contracts:
        incoming, outgoing = code_contracts[row["key"]]
        row["body"] += f'<div class="code-contract compact-contract"><span><strong>Input:</strong> {incoming}</span><span><strong>Output:</strong> {outgoing}</span></div>'
# Put the measured result, matching predictions and contrasting GOES failure in
# the main teaching sequence. Reference answers keep their own return links.
recorded_main_keys=('recorded-final','recorded-image','recorded-goes')
recorded_main=[next(s for s in slides if s['key']==key) for key in recorded_main_keys]
slides=[s for s in slides if s['key'] not in recorded_main_keys]
position=next(i for i,s in enumerate(slides) if s['key']=='final-turn')+1
slides[position:position]=recorded_main
main_count+=len(recorded_main)
for row,when in zip(recorded_main,('3:45 · RECORDED REHEARSAL','3:46 · RECORDED REHEARSAL','3:47 · RECORDED REHEARSAL')):
    row['time']=when
for row in slides:
    if row['key']=='result-meaning': row['time']='3:48'
    if row['key']=='reproduce': row['time']='3:49'
for slide in slides:
    slide['body']=slide['body'].replace('href="/images/', 'href="'+BASE+'images/')
    slide['body']=re.sub(r'(<table[^>]*>)', r'\1<tbody>', slide['body']).replace('</table>', '</tbody></table>')
indices={s['key']:i+1 for i,s in enumerate(slides)}
front='''---\ntheme: default\ntitle: Solar forecasting with agent-assisted experiments\nauthor: Anish Shah\ninfo: Solar Forecasting Lab\nclass: cover\nlayout: default\naspectRatio: 16/9\ncanvasWidth: 1280\ncolorSchema: light\ntransition: fade\nwakeLock: false\nfonts:\n  sans: IBM Plex Sans\n  mono: IBM Plex Mono\n  provider: none\nmdc: true\nhighlighter: shiki\ndrawings:\n  enabled: false\ndownload: false\nexportFilename: solar-autoresearch\n---\n\n'''
parts=[]
for i,s in enumerate(slides):
    fm='' if i==0 else ('\n---\nclass: '+s['kind']+'\n---\n\n' if s['kind'] else '\n---\n\n')
    answer=f'<a class="answer-link" href="{BASE}{indices[s["answer"]]}">Worked answer → {indices[s["answer"]]}</a>\n\n' if s['answer'] else ''
    returns=[x for x in slides if x['answer']==s['key']]
    back=('<div class="source-link">'+ ' · '.join(f'<a href="{BASE}{indices[x["key"]]}">Return to {x["title"]} →</a>' for x in returns)+'</div>') if returns else ''
    body=f'<div class="kicker">{s["time"]}'+(' · YOUR TURN' if s['kind']=='exercise' else '')+f'</div>\n\n{answer}# {s["title"]}\n\n{s["body"]}\n{back}\n\n<!--\n{s["notes"]}\nSource notes and recorded evidence: notes/sources.md.\n-->\n'
    parts.append(fm+body)
(ROOT/'slides.md').write_text(front+''.join(parts))
(ROOT/'notes/slide-map.json').write_text(json.dumps({'main_slides':main_count,'total_slides':len(slides),'slides':[{'number':i+1,**s} for i,s in enumerate(slides)]},indent=2))
(ROOT/'notes/facilitator-notes.md').write_text('# Solar forecasting workshop presenter notes\n\n'+ '\n\n'.join(f'## {i+1}. {s["title"]}\n\n{s["time"]}\n\n{s["notes"]}' for i,s in enumerate(slides)))
readme=ROOT/'README.md'
